const crypto = require('crypto');

function normalizeSpainPhone(raw) {
  if (raw == null || String(raw).trim() === '') {
    return { valid: false, reason: 'empty' };
  }
  let d = String(raw).replace(/\D/g, '');
  if (d.startsWith('0034')) d = d.slice(2);
  if (d.length === 9 && /^[6789]/.test(d)) d = '34' + d;
  if (d.length === 11 && d.startsWith('34')) {
    const national = d.slice(2);
    if (/^[6789]\d{8}$/.test(national)) {
      return { valid: true, phone_digits: d };
    }
  }
  return { valid: false, reason: 'invalid_spain' };
}

const item = $input.first().json;
const body = item.body ?? item;

if (Array.isArray(body.leads)) {
  const batch_id = String(body.batch_id || `batch_${Date.now()}`).slice(0, 120);
  const invalid_items = [];
  const leads = [];

  body.leads.forEach((L, index) => {
    const row = L || {};
    const phoneRaw = row.phone ?? row.telefono;
    const source = String(row.source || 'unknown').slice(0, 120);
    const norm = normalizeSpainPhone(phoneRaw);
    if (!norm.valid) {
      invalid_items.push({
        index,
        status: 'invalid',
        reason: norm.reason,
        source,
        phone: phoneRaw,
      });
      return;
    }
    const phone_digits = norm.phone_digits;
    const phone_hash = crypto.createHash('sha256').update(phone_digits, 'utf8').digest('hex');
    const now = new Date().toISOString();
    leads.push({
      index,
      phone_digits,
      phone_hash,
      source,
      row_number: row.row_number,
      sheet_tab: row.sheet_tab,
      claimed_at: now,
      first_seen_at: now,
      first_source: source,
    });
  });

  if (leads.length === 0 && body.leads.length > 0) {
    return [{ json: { route: 'invalid', reason: 'all_invalid', batch_id, invalid_items } }];
  }

  return [{ json: { route: 'batch', batch_id, leads, invalid_items } }];
}

const phoneRaw = body.phone;
const source = String(body.source || 'unknown').slice(0, 120);
const norm = normalizeSpainPhone(phoneRaw);

if (!norm.valid) {
  return [{ json: { route: 'invalid', reason: norm.reason, source } }];
}

const phone_digits = norm.phone_digits;
const phone_hash = crypto.createHash('sha256').update(phone_digits, 'utf8').digest('hex');
const now = new Date().toISOString();

return [{
  json: {
    route: 'register',
    phone_digits,
    phone_hash,
    source,
    claimed_at: now,
    first_seen_at: now,
    first_source: source,
  },
}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.phones) staticData.phones = {};

const prep = $('Prepare').first().json;
const phone = prep.phone_digits;
const now = new Date().toISOString();

function duplicateResponse(existing) {
  if (!staticData.phones[phone]) {
    staticData.phones[phone] = {
      phone_digits: phone,
      phone_hash: existing.phone_hash || prep.phone_hash,
      first_source: existing.first_source || prep.source,
      first_seen_at: existing.first_seen_at || prep.first_seen_at,
      claimed_at: existing.claimed_at || prep.claimed_at,
      meta_synced_at: ''
    };
  }
  return [{
    json: {
      ok: true,
      recorded: true,
      is_duplicate: true,
      skip_data_table: true,
      phone_digits: phone,
      source: prep.source,
      first_source: existing.first_source || prep.source,
      phone_hash: existing.phone_hash || prep.phone_hash,
      claimed_at: existing.claimed_at || prep.claimed_at,
      first_seen_at: existing.first_seen_at || prep.first_seen_at,
      duplicate_tag: 'duplicate',
      is_duplicate_label: 'yes'
    }
  }];
}

const tableRows = $('Get phone in table').all().map((i) => i.json).filter((r) => r && r.phone_digits === phone);
const tableRow = tableRows[0];

if (staticData.phones[phone]) {
  return duplicateResponse(staticData.phones[phone]);
}

if (tableRow) {
  return duplicateResponse({
    phone_hash: tableRow.phone_hash,
    first_source: tableRow.first_source || tableRow.source,
    first_seen_at: tableRow.first_seen_at || tableRow.received_at,
    claimed_at: tableRow.first_seen_at || tableRow.received_at
  });
}

staticData.phones[phone] = {
  phone_digits: phone,
  phone_hash: prep.phone_hash,
  first_source: prep.source,
  first_seen_at: prep.first_seen_at,
  claimed_at: prep.claimed_at,
  meta_synced_at: ''
};

return [{
  json: {
    ok: true,
    recorded: true,
    is_duplicate: false,
    skip_data_table: false,
    phone_digits: phone,
    phone_hash: prep.phone_hash,
    source: prep.source,
    claimed_at: prep.claimed_at,
    first_seen_at: prep.first_seen_at,
    first_source: prep.source
  }
}];

const r = $input.first().json;
const receivedAt = new Date().toISOString();
const isDup = Boolean(r.is_duplicate);
return [{
  json: {
    ...r,
    duplicate_tag: isDup ? 'duplicate' : 'new',
    is_duplicate: isDup ? 'yes' : 'no',
    received_at: receivedAt,
    first_source: r.first_source || r.source || '',
    first_seen_at: r.first_seen_at || r.claimed_at || receivedAt,
    phone_hash: r.phone_hash || ''
  }
}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.phones) staticData.phones = {};

const prep = $('Prepare').first().json;
const batch_id = prep.batch_id;
const leads = prep.leads || [];
const invalid_items = prep.invalid_items || [];
const now = new Date().toISOString();

const tableRows = $('Load registry from table').all()
  .map((i) => i.json)
  .filter((r) => r && r.phone_digits);
const tableByPhone = {};
for (const row of tableRows) {
  if (!tableByPhone[row.phone_digits]) tableByPhone[row.phone_digits] = row;
}

const seenInBatch = new Set();
const results = [...invalid_items];
const insert_rows = [];

function duplicateResult(lead, existing) {
  return {
    index: lead.index,
    status: 'duplicate',
    phone_digits: lead.phone_digits,
    source: lead.source,
    first_source: existing.first_source || lead.first_source,
    phone_hash: existing.phone_hash || lead.phone_hash,
    duplicate_tag: 'duplicate',
    is_duplicate: 'yes',
    message: 'duplicate_not_processed',
  };
}

for (const lead of leads) {
  const phone = lead.phone_digits;

  if (seenInBatch.has(phone)) {
    const ex = staticData.phones[phone] || {
      first_source: lead.first_source,
      phone_hash: lead.phone_hash,
    };
    results.push(duplicateResult(lead, ex));
    continue;
  }
  seenInBatch.add(phone);

  if (staticData.phones[phone]) {
    results.push(duplicateResult(lead, staticData.phones[phone]));
    continue;
  }

  const tableRow = tableByPhone[phone];
  if (tableRow) {
    const existing = {
      phone_hash: tableRow.phone_hash || lead.phone_hash,
      first_source: tableRow.first_source || tableRow.source || lead.source,
      first_seen_at: tableRow.first_seen_at || tableRow.received_at,
      claimed_at: tableRow.first_seen_at || tableRow.received_at,
    };
    staticData.phones[phone] = {
      phone_digits: phone,
      phone_hash: existing.phone_hash,
      first_source: existing.first_source,
      first_seen_at: existing.first_seen_at || lead.first_seen_at,
      claimed_at: existing.claimed_at || lead.claimed_at,
      meta_synced_at: '',
    };
    results.push(duplicateResult(lead, existing));
    continue;
  }

  staticData.phones[phone] = {
    phone_digits: phone,
    phone_hash: lead.phone_hash,
    first_source: lead.source,
    first_seen_at: lead.first_seen_at,
    claimed_at: lead.claimed_at,
    meta_synced_at: '',
  };

  const receivedAt = now;
  results.push({
    index: lead.index,
    status: 'new',
    phone_digits: phone,
    source: lead.source,
    first_source: lead.source,
    duplicate_tag: 'new',
    is_duplicate: 'no',
    phone_hash: lead.phone_hash,
    first_seen_at: lead.first_seen_at,
    received_at: receivedAt,
  });

  insert_rows.push({
    phone_digits: phone,
    duplicate_tag: 'new',
    is_duplicate: 'no',
    source: lead.source,
    first_source: lead.source,
    received_at: receivedAt,
    first_seen_at: lead.first_seen_at,
    phone_hash: lead.phone_hash,
  });
}

const stats = {
  input: leads.length + invalid_items.length,
  new: results.filter((r) => r.status === 'new').length,
  duplicate: results.filter((r) => r.status === 'duplicate').length,
  invalid: results.filter((r) => r.status === 'invalid').length,
  inserted: insert_rows.length,
};

return [{
  json: {
    ok: true,
    batch_id,
    stats,
    results,
    insert_rows,
  },
}];
